  int get hashCode =>
      importId.hashCode ^ stagingTicket.hashCode ^ maxBytes.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is ImportTicket &&
          runtimeType == other.runtimeType &&
