/// 录音状态，契约第 3 节「录音」行。
enum RecordingState {
  idle,
  preparing,
  recording,
  paused,
  stopping,
  saved,

  /// 被来电、系统回收等打断。**不是** paused：界面不能继续显示正在收音。
  interrupted,

  /// 有已封闭片段可以救回来，但可能缺尾巴。
  recoverable,
  error;

  static Future<RecordingState?> fromWire({required String value}) =>
      RustLib.instance.api.diaryCoreModelRecordingStateFromWire(value: value);

  /// 是否还在进行中（重启后需要收拾的那批）。
  Future<bool> isOpen() =>
      RustLib.instance.api.diaryCoreModelRecordingStateIsOpen(that: this);

  Future<void> wire() =>
      RustLib.instance.api.diaryCoreModelRecordingStateWire(that: this);
}

/// 恢复到新库的结果（`backups.restore`）。
class RestoreReport {
  /// 恢复出来的资料库文件路径：调用方拿它直接 `Core::open`。
  final String libraryPath;

  /// 恢复出来的资料库根目录（原件与资料库文件所在目录）。
  final String rootDir;
  final PlatformInt64 schemaVersion;
  final String apiVersion;
  final String coreVersion;

  /// 备份包的导出时刻。
  final DateTime createdAt;
  final PlatformInt64 byteSize;
  final PlatformInt64 blobCount;
  final PlatformInt64 blobBytes;
  final PlatformInt64 transientClipCount;
  final BackupCounts counts;

  /// 如实说明恢复出来的库里「还没做完」的东西（不假装完成）。
  final List<String> warnings;

  const RestoreReport({
    required this.libraryPath,
    required this.rootDir,
    required this.schemaVersion,
    required this.apiVersion,
    required this.coreVersion,
    required this.createdAt,
    required this.byteSize,
    required this.blobCount,
    required this.blobBytes,
    required this.transientClipCount,
    required this.counts,
    required this.warnings,
  });

  @override
  int get hashCode =>
      libraryPath.hashCode ^
      rootDir.hashCode ^
      schemaVersion.hashCode ^
      apiVersion.hashCode ^
      coreVersion.hashCode ^
      createdAt.hashCode ^
      byteSize.hashCode ^
      blobCount.hashCode ^
      blobBytes.hashCode ^
      transientClipCount.hashCode ^
      counts.hashCode ^
      warnings.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is RestoreReport &&
          runtimeType == other.runtimeType &&
          libraryPath == other.libraryPath &&
          rootDir == other.rootDir &&
          schemaVersion == other.schemaVersion &&
          apiVersion == other.apiVersion &&
          coreVersion == other.coreVersion &&
          createdAt == other.createdAt &&
          byteSize == other.byteSize &&
          blobCount == other.blobCount &&
          blobBytes == other.blobBytes &&
          transientClipCount == other.transientClipCount &&
          counts == other.counts &&
          warnings == other.warnings;
}

/// 检索过滤条件，契约第 2.6 节。
class SearchFilters {
  final String? fromDayKey;
  final String? toDayKey;
  final List<SourceKind> kinds;

  /// 限定来源范围。`None` 才是不限；`Some([])` 是「什么都不看」（与 `indexes.status`
  /// 的空范围同义），不是「看全部」。
  final List<String>? sourceScope;
  final bool includeOldDiaryVersions;
  final bool includeTrashed;

  const SearchFilters({
    this.fromDayKey,
    this.toDayKey,
    required this.kinds,
    this.sourceScope,
    required this.includeOldDiaryVersions,
    required this.includeTrashed,
  });

  static Future<SearchFilters> default_() =>
      RustLib.instance.api.diaryCoreModelSearchFiltersDefault();

  @override
  int get hashCode =>
      fromDayKey.hashCode ^
      toDayKey.hashCode ^
      kinds.hashCode ^
      sourceScope.hashCode ^
      includeOldDiaryVersions.hashCode ^
      includeTrashed.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is SearchFilters &&
          runtimeType == other.runtimeType &&
          fromDayKey == other.fromDayKey &&
          toDayKey == other.toDayKey &&
          kinds == other.kinds &&
          sourceScope == other.sourceScope &&
          includeOldDiaryVersions == other.includeOldDiaryVersions &&
          includeTrashed == other.includeTrashed;
}

/// 一条检索命中，契约第 2.6 节。
class SearchHit {
  /// 稳定标识：直接用片段 ID。同一份内容在不同页里出现时是同一个值。
  final String hitId;

  /// 同一来源的命中归到一组，避免一份长材料占满结果。
  final String groupId;
  final SourceKind sourceKind;
  final List<MatchedBy> matchedBy;
  final Coverage coverage;
  final String? sourceId;
  final String? revisionId;
  final String? dayKey;

  /// 原件名（有资产时）；纯文字来源没有名字。
  final String? title;

  /// 命中位置附近的摘录。
  final String? snippet;

  /// 高亮区间，下标相对 `snippet`。
  final List<TextRange> highlights;
  final SourceLocator? locator;

  const SearchHit({
    required this.hitId,
    required this.groupId,
    required this.sourceKind,
    required this.matchedBy,
    required this.coverage,
    this.sourceId,
    this.revisionId,
    this.dayKey,
    this.title,
    this.snippet,
    required this.highlights,
    this.locator,
  });

  @override
  int get hashCode =>
      hitId.hashCode ^
      groupId.hashCode ^
      sourceKind.hashCode ^
      matchedBy.hashCode ^
      coverage.hashCode ^
      sourceId.hashCode ^
      revisionId.hashCode ^
      dayKey.hashCode ^
      title.hashCode ^
      snippet.hashCode ^
      highlights.hashCode ^
      locator.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is SearchHit &&
          runtimeType == other.runtimeType &&
          hitId == other.hitId &&
          groupId == other.groupId &&
          sourceKind == other.sourceKind &&
          matchedBy == other.matchedBy &&
          coverage == other.coverage &&
          sourceId == other.sourceId &&
          revisionId == other.revisionId &&
          dayKey == other.dayKey &&
          title == other.title &&
          snippet == other.snippet &&
          highlights == other.highlights &&
          locator == other.locator;
}

/// 检索模式，契约第 2.6 节。三种都实现了：`Hybrid` 是 RRF 融合（#51，B3c-3），
/// **分两阶段给**（#69）——`start_search` 先只算关键词那一路并报 `keyword_ready`，
/// 显式调用 `upgrade_search_to_hybrid(sessionId)` 才融合并报 `hybrid_ready`。
/// 语义未就绪时**退化为关键词并在 `warnings` 里明说**（不静默，也不假装跑过混合）。
enum SearchMode {
  keyword,
  semantic,
  hybrid;

  static Future<SearchMode?> fromWire({required String value}) =>
      RustLib.instance.api.diaryCoreModelSearchModeFromWire(value: value);

  Future<void> wire() =>
      RustLib.instance.api.diaryCoreModelSearchModeWire(that: this);
}

/// 检索阶段，契约第 2.6 节。
///
/// 混合检索的阶段流程（#69）：`start_search(mode = hybrid)` → `keyword_ready`
/// （只有关键词那一路的结果）→ `upgrade_search_to_hybrid(sessionId)` → `hybrid_ready`
/// （融合 + 重排后的结果）→ 翻完最后一页 `done`。语义拿不出证据时升级**不会**给出
/// `hybrid_ready`，阶段如实停在 `keyword_ready`。取消 → `cancelled`。
enum SearchPhase {
  initial,
  keywordReady,
  hybridReady,
  done,
  cancelled;

  static Future<SearchPhase?> fromWire({required String value}) =>
      RustLib.instance.api.diaryCoreModelSearchPhaseFromWire(value: value);

  Future<void> wire() =>
      RustLib.instance.api.diaryCoreModelSearchPhaseWire(that: this);
}

/// 一次检索请求，契约第 2.6 节。
class SearchRequest {
  /// 用户原样输入，是普通检索文字，不直接当 FTS 表达式执行。
  final String query;
  final SearchMode mode;
  final SearchFilters filters;
  final PlatformInt64 pageSize;

  const SearchRequest({
    required this.query,
    required this.mode,
    required this.filters,
    required this.pageSize,
  });

  @override
  int get hashCode =>
      query.hashCode ^ mode.hashCode ^ filters.hashCode ^ pageSize.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is SearchRequest &&
          runtimeType == other.runtimeType &&
          query == other.query &&
          mode == other.mode &&
          filters == other.filters &&
          pageSize == other.pageSize;
}

/// 检索会话的完整快照，契约第 2.6 节。
///
/// 每次返回的是**当前页的完整快照**，前端按 `hit_id` 更新，不要把两份快照
/// 当增量拼接。
class SearchSnapshot {
  final String sessionId;
  final PlatformInt64 queryRevision;
  final SearchPhase phase;
  final List<SearchHit> results;
  final String? cursor;
  final Coverage indexCoverage;
  final List<String> warnings;

  const SearchSnapshot({
    required this.sessionId,
    required this.queryRevision,
    required this.phase,
    required this.results,
    this.cursor,
    required this.indexCoverage,
    required this.warnings,
  });

  @override
  int get hashCode =>
      sessionId.hashCode ^
      queryRevision.hashCode ^
      phase.hashCode ^
      results.hashCode ^
      cursor.hashCode ^
      indexCoverage.hashCode ^
      warnings.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is SearchSnapshot &&
          runtimeType == other.runtimeType &&
          sessionId == other.sessionId &&
          queryRevision == other.queryRevision &&
          phase == other.phase &&
          results == other.results &&
          cursor == other.cursor &&
          indexCoverage == other.indexCoverage &&
          warnings == other.warnings;
}

/// 材料类型，契约第 2.3 节的 SourceKind。
enum SourceKind {
  text,
  image,
  audio,
  video,
  file,
  link;

  /// 认不出的类型落到 `file`——这是「有原件但不知道是什么」最接近的诚实答案，
  /// 而不是丢掉这条命中。
  static Future<SourceKind> fromWire({required String value}) =>
      RustLib.instance.api.diaryCoreModelSourceKindFromWire(value: value);

  Future<void> wire() =>
      RustLib.instance.api.diaryCoreModelSourceKindWire(that: this);
}

/// 定位结果：前端能否打开原件，以及不能打开时的真实原因。
class SourceLocation {
  final String sourceRef;
  final SourceLocator locator;
  final bool available;
  final String? assetId;
  final String? reason;

  const SourceLocation({
    required this.sourceRef,
    required this.locator,
    required this.available,
    this.assetId,
    this.reason,
  });

  @override
  int get hashCode =>
      sourceRef.hashCode ^
      locator.hashCode ^
      available.hashCode ^
      assetId.hashCode ^
      reason.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is SourceLocation &&
          runtimeType == other.runtimeType &&
          sourceRef == other.sourceRef &&
          locator == other.locator &&
          available == other.available &&
          assetId == other.assetId &&
          reason == other.reason;
}

/// 定位信息。每个 locator 都带 sourceRevisionId，保证定位到当时的原文版本。
class SourceLocator {
  final LocatorType locatorType;
  final String sourceRevisionId;

  /// 文字区间：Unicode 标量值计数，左闭右开。
  final PlatformInt64? textStart;
  final PlatformInt64? textEnd;
  final PlatformInt64? startMs;
  final PlatformInt64? endMs;

  /// 页码从 1 开始；无法可靠定位时为 None，不伪造。
  final PlatformInt64? pageNumber;
  final String? blockId;

  /// 图片归一化矩形。
  final F64Array4? rect;
  final String? assetId;

  const SourceLocator({
    required this.locatorType,
    required this.sourceRevisionId,
    this.textStart,
    this.textEnd,
    this.startMs,
    this.endMs,
    this.pageNumber,
    this.blockId,
    this.rect,
    this.assetId,
  });

  static Future<SourceLocator> document({
    required String sourceRevisionId,
    PlatformInt64? pageNumber,
    String? blockId,
  }) => RustLib.instance.api.diaryCoreModelSourceLocatorDocument(
    sourceRevisionId: sourceRevisionId,
    pageNumber: pageNumber,
    blockId: blockId,
  );

  static Future<SourceLocator> textRange({
    required String sourceRevisionId,
    required PlatformInt64 start,
    required PlatformInt64 end,
  }) => RustLib.instance.api.diaryCoreModelSourceLocatorTextRange(
    sourceRevisionId: sourceRevisionId,
    start: start,
    end: end,
  );

  @override
  int get hashCode =>
      locatorType.hashCode ^
      sourceRevisionId.hashCode ^
      textStart.hashCode ^
      textEnd.hashCode ^
      startMs.hashCode ^
      endMs.hashCode ^
      pageNumber.hashCode ^
      blockId.hashCode ^
      rect.hashCode ^
      assetId.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is SourceLocator &&
          runtimeType == other.runtimeType &&
          locatorType == other.locatorType &&
          sourceRevisionId == other.sourceRevisionId &&
          textStart == other.textStart &&
          textEnd == other.textEnd &&
          startMs == other.startMs &&
          endMs == other.endMs &&
          pageNumber == other.pageNumber &&
          blockId == other.blockId &&
          rect == other.rect &&
          assetId == other.assetId;
}

/// 原始文字或来源元数据的某一次修订。旧版本永远保留。
class SourceRevision {
  final String revisionId;
  final String sourceId;
  final String? parentRevisionId;
  final String? text;
  final String? assetId;
  final AuthorType authorType;
  final DateTime occurredAt;

  const SourceRevision({
    required this.revisionId,
    required this.sourceId,
    this.parentRevisionId,
    this.text,
    this.assetId,
    required this.authorType,
    required this.occurredAt,
  });

  @override
  int get hashCode =>
      revisionId.hashCode ^
      sourceId.hashCode ^
      parentRevisionId.hashCode ^
      text.hashCode ^
      assetId.hashCode ^
      authorType.hashCode ^
      occurredAt.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is SourceRevision &&
          runtimeType == other.runtimeType &&
          revisionId == other.revisionId &&
          sourceId == other.sourceId &&
          parentRevisionId == other.parentRevisionId &&
          text == other.text &&
          assetId == other.assetId &&
          authorType == other.authorType &&
          occurredAt == other.occurredAt;
}

/// 命中里的高亮区间，**下标相对 `snippet`**，不是相对整段正文。
class TextRange {
  final PlatformInt64 start;
  final PlatformInt64 end;

  const TextRange({required this.start, required this.end});

  @override
  int get hashCode => start.hashCode ^ end.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is TextRange &&
          runtimeType == other.runtimeType &&
          start == other.start &&
          end == other.end;
}
